(function(){
'use strict';

/* ── Accordion ──────────────────────────────────────────────── */
document.querySelectorAll('.eltiz-accordion').forEach(function(acc){
  acc.querySelectorAll('.eltiz-accordion__item-title').forEach(function(title){
    title.addEventListener('click', function(){
      var item    = title.closest('.eltiz-accordion__item');
      var content = item.querySelector('.eltiz-accordion__item-content');
      var isOpen  = item.classList.contains('is-active');
      var isExcl  = acc.dataset.exclusive !== 'false';
      if(isExcl){
        acc.querySelectorAll('.eltiz-accordion__item.is-active').forEach(function(open){
          open.classList.remove('is-active');
          var c = open.querySelector('.eltiz-accordion__item-content');
          if(c){ c.style.maxHeight = null; }
        });
      }
      if(!isOpen){
        item.classList.add('is-active');
        if(content){ content.style.maxHeight = content.scrollHeight + 'px'; }
      }
    });
  });
  // Open first item by default.
  var first = acc.querySelector('.eltiz-accordion__item');
  if(first){
    first.classList.add('is-active');
    var c = first.querySelector('.eltiz-accordion__item-content');
    if(c){ c.style.maxHeight = c.scrollHeight + 'px'; }
  }
});

/* ── Tabs ───────────────────────────────────────────────────── */
document.querySelectorAll('.eltiz-tabs').forEach(function(tabs){
  var navItems  = tabs.querySelectorAll('.eltiz-tabs__nav-item');
  var tabPanels = tabs.querySelectorAll('.eltiz-tabs__panel');
  navItems.forEach(function(nav, i){
    nav.addEventListener('click', function(){
      navItems.forEach(function(n){ n.classList.remove('is-active'); n.setAttribute('aria-selected','false'); });
      tabPanels.forEach(function(p){ p.classList.remove('is-active'); p.setAttribute('hidden',''); });
      nav.classList.add('is-active');
      nav.setAttribute('aria-selected','true');
      if(tabPanels[i]){ tabPanels[i].classList.add('is-active'); tabPanels[i].removeAttribute('hidden'); }
    });
  });
  if(navItems[0]){ navItems[0].click(); }
});

/* ── Toggle ─────────────────────────────────────────────────── */
document.querySelectorAll('.eltiz-toggle').forEach(function(toggle){
  toggle.querySelectorAll('.eltiz-toggle__item-title').forEach(function(title){
    title.addEventListener('click', function(){
      var item    = title.closest('.eltiz-toggle__item');
      var content = item.querySelector('.eltiz-toggle__item-content');
      item.classList.toggle('is-active');
      if(item.classList.contains('is-active')){
        if(content){ content.style.maxHeight = content.scrollHeight + 'px'; }
      } else {
        if(content){ content.style.maxHeight = null; }
      }
    });
  });
});

/* ── Counter ─────────────────────────────────────────────────── */
function animateCounter(el){
  var start    = parseInt(el.dataset.start  || 0, 10);
  var end      = parseInt(el.dataset.end    || 0, 10);
  var duration = parseInt(el.dataset.duration || 2000, 10);
  var startTime = null;
  function step(timestamp){
    if(!startTime) startTime = timestamp;
    var progress = Math.min((timestamp - startTime) / duration, 1);
    var ease     = 1 - Math.pow(1 - progress, 3); // cubic ease-out
    el.textContent = Math.round(start + ease * (end - start)).toLocaleString();
    if(progress < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}
if('IntersectionObserver' in window){
  var counterObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        animateCounter(entry.target);
        counterObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.5 });
  document.querySelectorAll('.eltiz-counter__number').forEach(function(el){
    counterObserver.observe(el);
  });
} else {
  document.querySelectorAll('.eltiz-counter__number').forEach(animateCounter);
}

/* ── Countdown ───────────────────────────────────────────────── */
document.querySelectorAll('.eltiz-countdown').forEach(function(el){
  var due = new Date(el.dataset.due || '').getTime();
  if(!due || isNaN(due)) return;
  function tick(){
    var diff = due - Date.now();
    if(diff <= 0){ diff = 0; }
    var d = Math.floor(diff / 86400000);
    var h = Math.floor((diff % 86400000) / 3600000);
    var m = Math.floor((diff % 3600000)  / 60000);
    var s = Math.floor((diff % 60000)    / 1000);
    ['days','hours','minutes','seconds'].forEach(function(unit, i){
      var num = [d,h,m,s][i];
      var seg = el.querySelector('.eltiz-countdown__'+unit+' .eltiz-countdown__number');
      if(seg) seg.textContent = String(num).padStart(2,'0');
    });
    if(diff > 0) setTimeout(tick, 1000);
  }
  tick();
});

/* ── Gallery Lightbox ────────────────────────────────────────── */
(function(){
  var overlay = null;
  function openLightbox(src, alt){
    if(!overlay){
      overlay = document.createElement('div');
      overlay.className = 'eltiz-lightbox';
      overlay.innerHTML = '<div class="eltiz-lightbox__backdrop"></div><div class="eltiz-lightbox__content"><img class="eltiz-lightbox__img" src="" alt=""><button class="eltiz-lightbox__close" aria-label="Close">&times;</button></div>';
      document.body.appendChild(overlay);
      overlay.querySelector('.eltiz-lightbox__backdrop').addEventListener('click', closeLightbox);
      overlay.querySelector('.eltiz-lightbox__close').addEventListener('click', closeLightbox);
      document.addEventListener('keydown', function(e){ if(e.key === 'Escape') closeLightbox(); });
    }
    overlay.querySelector('.eltiz-lightbox__img').src = src;
    overlay.querySelector('.eltiz-lightbox__img').alt = alt || '';
    overlay.classList.add('is-open');
    document.body.style.overflow = 'hidden';
  }
  function closeLightbox(){
    if(overlay){ overlay.classList.remove('is-open'); }
    document.body.style.overflow = '';
  }
  document.querySelectorAll('.eltiz-gallery[data-lightbox="yes"] .eltiz-gallery__item').forEach(function(item){
    item.style.cursor = 'pointer';
    item.addEventListener('click', function(){
      var img = item.querySelector('img');
      if(img) openLightbox(img.src, img.alt);
    });
  });
})();

/* ── Progress Bar ─────────────────────────────────────────────── */
if('IntersectionObserver' in window){
  var progressObserver = new IntersectionObserver(function(entries){
    entries.forEach(function(entry){
      if(entry.isIntersecting){
        var bar = entry.target.querySelector('.eltiz-progress-bar__fill');
        if(bar){ bar.style.width = bar.dataset.percent + '%'; }
        progressObserver.unobserve(entry.target);
      }
    });
  }, { threshold: 0.3 });
  document.querySelectorAll('.eltiz-progress-bar').forEach(function(el){
    progressObserver.observe(el);
  });
}

/* ── Social Icons — no-op, pure CSS ─────────────────────────── */

/* ── Search Form — submit on enter ──────────────────────────── */
document.querySelectorAll('.eltiz-search-form').forEach(function(form){
  var input  = form.querySelector('input[type="search"]');
  var button = form.querySelector('button[type="submit"]');
  if(input && button){
    input.addEventListener('keydown', function(e){
      if(e.key === 'Enter'){ form.submit(); }
    });
  }
});

})();
